function isRecentIsoTimestamp(value: string | null | undefined, maxAgeMs: number): boolean {
  if (!value) return false;
  const parsed = new Date(value).getTime();
  if (!Number.isFinite(parsed)) return false;
  return Date.now() - parsed <= maxAgeMs;
}

function haversineMeters(
  lat1: number,
  lng1: number,
  lat2: number,
  lng2: number,
): number {
  const R = 6371000;
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLng = ((lng2 - lng1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos((lat1 * Math.PI) / 180) *
      Math.cos((lat2 * Math.PI) / 180) *
      Math.sin(dLng / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

const hasValidCoordinate = (coord: any) => {
  if (!coord) return false;
  const lat = Number(coord.latitude ?? coord.lat);
  const lng = Number(coord.longitude ?? coord.lng ?? coord.lon);
  return Number.isFinite(lat) && Number.isFinite(lng);
};

const toSafeCoordinate = (coord: any) => {
  if (!hasValidCoordinate(coord)) return null;
  return {
    latitude: Number(coord.latitude ?? coord.lat),
    longitude: Number(coord.longitude ?? coord.lng ?? coord.lon),
  };
};

const toSafeMapLocation = (coord: any): { lat: number; lng: number } | null => {
  const safe = toSafeCoordinate(coord);
  if (!safe) return null;
  if (safe.latitude < -90 || safe.latitude > 90) return null;
  if (safe.longitude < -180 || safe.longitude > 180) return null;
  return { lat: safe.latitude, lng: safe.longitude };
};

const toMapMotionGpsSample = (coord: any): MapMotionGpsSample | null => {
  const safe = toSafeCoordinate(coord);
  if (!safe) return null;
  if (safe.latitude < -90 || safe.latitude > 90) return null;
  if (safe.longitude < -180 || safe.longitude > 180) return null;
  const timestamp = Number(coord?.timestamp);
  return {
    latitude: safe.latitude,
    longitude: safe.longitude,
    altitudeFt: typeof coord?.altitudeFt === 'number' && Number.isFinite(coord.altitudeFt) ? coord.altitudeFt : null,
    speedMph: typeof coord?.speedMph === 'number' && Number.isFinite(coord.speedMph) ? coord.speedMph : null,
    headingDeg: typeof coord?.headingDeg === 'number' && Number.isFinite(coord.headingDeg) ? coord.headingDeg : null,
    accuracyM: typeof coord?.accuracyM === 'number' && Number.isFinite(coord.accuracyM) ? coord.accuracyM : null,
    timestamp: Number.isFinite(timestamp) ? timestamp : Date.now(),
  };
};

function toNavigateWeatherCoordinate(
  coord: unknown,
  label?: string | null,
): WeatherCoordinate | null {
  const safe = toSafeMapLocation(coord);
  if (!safe) return null;
  return {
    lat: safe.lat,
    lng: safe.lng,
    label: typeof label === 'string' && label.trim() ? label.trim() : undefined,
  };
}

function firstNavigateWeatherCoordinate(
  candidates: { coord: unknown; label?: string | null }[],
): WeatherCoordinate | null {
  for (const candidate of candidates) {
    const coordinate = toNavigateWeatherCoordinate(candidate.coord, candidate.label);
    if (coordinate) return coordinate;
  }
  return null;
}

function dedupeWeatherCoordinates(coordinates: WeatherCoordinate[]): WeatherCoordinate[] {
  const seen = new Set<string>();
  return coordinates.filter((coordinate) => {
    if (!Number.isFinite(coordinate.lat) || !Number.isFinite(coordinate.lng)) return false;
    const key = `${coordinate.lat.toFixed(4)}:${coordinate.lng.toFixed(4)}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function getRouteWeatherRiskPoint(
  points: readonly { lat: number; lng: number; hazardLevel?: string | null }[],
): { lat: number; lng: number } | null {
  const priority = ['hazardous', 'warning', 'caution'];
  for (const level of priority) {
    const point = points.find((candidate) => candidate.hazardLevel === level);
    if (point && toSafeMapLocation(point)) return point;
  }
  return null;
}

function buildNavigateRouteWeatherCoordinates(
  routePoints: readonly { lat: number; lng: number }[],
  riskPoint?: { lat: number; lng: number } | null,
): WeatherCoordinate[] {
  const validPoints = routePoints
    .map((point) => toNavigateWeatherCoordinate(point))
    .filter((point): point is WeatherCoordinate => !!point);
  if (validPoints.length < 2) return [];

  const start = validPoints[0];
  const end = validPoints[validPoints.length - 1];
  const middle = validPoints[Math.floor((validPoints.length - 1) / 2)];
  const riskCoordinate = riskPoint ? toNavigateWeatherCoordinate(riskPoint) : null;

  return dedupeWeatherCoordinates([
    { ...start, label: 'Route start' },
    { ...(riskCoordinate ?? middle), label: riskCoordinate ? 'Highest-risk route segment' : 'Route midpoint' },
    { ...end, label: 'Route destination' },
  ]);
}

function formatNavMiles(value: number | null | undefined): string {
  if (value == null || !Number.isFinite(value)) return '--';
  if (value < 10) return `${value.toFixed(1)} mi`;
  return `${Math.round(value)} mi`;
}

function formatNavMeters(value: number | null | undefined): string {
  if (value == null || !Number.isFinite(value)) return '--';
  if (value < 160) {
    return `${Math.max(Math.round(value / 5) * 5, 5)} ft`;
  }
  return formatNavMiles(value / 1609.344);
}

function routeConfidenceTimelineConfidenceFromPercent(
  value: number | null | undefined,
): RouteConfidenceTimelineOverlay['confidenceLevel'] {
  if (value == null || !Number.isFinite(value)) return 'unknown';
  if (value >= 70) return 'high';
  if (value >= 45) return 'medium';
  if (value > 0) return 'low';
  return 'unknown';
}

function routeConfidenceTimelineTimestamp(value: unknown): string | null {
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return null;
    const parsed = Date.parse(trimmed);
    return Number.isFinite(parsed) ? new Date(parsed).toISOString() : trimmed;
  }
  if (typeof value === 'number' && Number.isFinite(value)) {
    const millis = value > 0 && value < 100000000000 ? value * 1000 : value;
    const parsed = new Date(millis);
    return Number.isFinite(parsed.getTime()) ? parsed.toISOString() : null;
  }
  return null;
}

function routeConfidenceTimelineString(value: unknown): string | null {
  if (typeof value === 'string') {
    const trimmed = value.trim();
    return trimmed ? trimmed : null;
  }
  if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  return null;
}

function routeConfidenceTimelineSource(
  id: string,
  label: string,
  observedAt: unknown,
  freshness: RouteConfidenceTimelineOverlay['source']['freshness'] = 'fresh',
): RouteConfidenceTimelineOverlay['source'] {
  return {
    id,
    label,
    sourceType: 'navigate',
    observedAt: routeConfidenceTimelineTimestamp(observedAt),
    freshness,
  };
}

function navigateRouteConfidenceGeometry(
  routePoints: readonly { lat: number; lng: number }[],
  geometryVersion: string,
  distanceMeters?: number | null,
): RouteGeometry | null {
  const coordinates = routePoints
    .map((point) => ({
      lat: Number(point.lat),
      lng: Number(point.lng),
    }))
    .filter((point) => Number.isFinite(point.lat) && Number.isFinite(point.lng));
  if (coordinates.length < 2) return null;
  return {
    origin: coordinates[0],
    destination: coordinates[coordinates.length - 1],
    waypoints: coordinates.slice(1, -1),
    coordinates,
    distanceMeters: Number.isFinite(Number(distanceMeters)) ? Number(distanceMeters) : null,
    durationSeconds: null,
    bbox: null,
    corridor: null,
    segments: [],
    providerMetadata: {
      geometryVersion,
      source: 'navigate_displayed_route',
    },
  };
}

function navigateTimelineMeasure(
  routePoints: readonly { lat: number; lng: number }[],
  distanceMeters?: number | null,
): number {
  const explicit = Number(distanceMeters);
  if (Number.isFinite(explicit) && explicit > 0) return explicit;
  return Math.max((routePoints.length - 1) * 1000, 1000);
}

function buildNavigateRouteConfidenceTimelineOverlays(args: {
  totalMeasure: number;
  routeConfidenceSummary: { confidence?: number | null; status?: string | null; summary?: string | null } | null;
  cacheSnapshot: ReturnType<typeof evaluateCacheReadiness> | null;
  routeHazardIntel: { headline?: string | null; summaryLine?: string | null } | null;
  weatherObservedAt?: unknown;
  weatherSource?: string | null;
  generatedAt: string;
}): RouteConfidenceTimelineOverlay[] {
  const total = Math.max(args.totalMeasure, 1);
  const overlays: RouteConfidenceTimelineOverlay[] = [];
  const confidence = Number(args.routeConfidenceSummary?.confidence);
  if (Number.isFinite(confidence)) {
    const confidenceLevel = routeConfidenceTimelineConfidenceFromPercent(confidence);
    overlays.push({
      id: 'navigate-route-confidence-summary',
      startMeasure: 0,
      endMeasure: total,
      label: confidenceLevel === 'low' || confidenceLevel === 'unknown'
        ? 'Route confidence uncertainty'
        : 'Route confidence baseline',
      confidenceLevel,
      conditionState: confidenceLevel === 'low' || confidenceLevel === 'unknown' ? 'unknown' : 'normal',
      driverCategory: 'terrain_weather',
      source: routeConfidenceTimelineSource('route-confidence-summary', 'Route confidence summary', args.generatedAt),
      detail: routeConfidenceTimelineString(args.routeConfidenceSummary?.summary),
    });
  }

  if (args.cacheSnapshot && !args.cacheSnapshot.cached_route_available) {
    overlays.push({
      id: 'navigate-offline-map-gap',
      startMeasure: total * 0.35,
      endMeasure: total * 0.62,
      label: 'Offline map gap',
      confidenceLevel: args.cacheSnapshot.offline_cache_ready ? 'low' : 'unknown',
      conditionState: 'unknown',
      driverCategory: 'offline_coverage',
      source: routeConfidenceTimelineSource(
        'offline-cache-readiness',
        'Offline cache readiness',
        args.cacheSnapshot.evaluated_at || null,
        args.cacheSnapshot.offline_cache_ready ? 'fresh' : 'missing',
      ),
      detail: 'Offline package coverage is incomplete for this route context.',
    });
  }

  if (args.routeHazardIntel) {
    overlays.push({
      id: 'navigate-weather-risk',
      startMeasure: total * 0.55,
      endMeasure: total * 0.86,
      label: args.routeHazardIntel.headline ?? 'Weather-exposed corridor',
      confidenceLevel: args.weatherSource === 'live' ? 'high' : 'medium',
      conditionState: 'known_risky',
      driverCategory: 'terrain_weather',
      source: routeConfidenceTimelineSource(
        'route-corridor-weather',
        'Route corridor weather',
        args.weatherObservedAt ?? args.generatedAt,
        args.weatherSource === 'cache_stale' ? 'stale' : 'fresh',
      ),
      detail: routeConfidenceTimelineString(args.routeHazardIntel.summaryLine),
    });
  }

  return overlays;
}

function routeConfidenceTimelinePointAtMeasure(
  routePoints: readonly { lat: number; lng: number }[],
  item: RouteConfidenceTimelineItem,
  totalMeasure: number,
): { lat: number; lng: number } | null {
  if (routePoints.length === 0) return null;
  const midpoint = (item.startMeasure + item.endMeasure) / 2;
  const ratio = totalMeasure > 0 ? Math.max(0, Math.min(1, midpoint / totalMeasure)) : 0;
  const index = Math.max(0, Math.min(routePoints.length - 1, Math.round(ratio * (routePoints.length - 1))));
  const point = routePoints[index];
  return point && Number.isFinite(point.lat) && Number.isFinite(point.lng)
    ? { lat: point.lat, lng: point.lng }
    : null;
}

function routeConfidenceTimelineTone(item: RouteConfidenceTimelineItem): string {
  if (item.conditionState === 'known_risky') return '#EF5350';
  if (item.confidenceLevel === 'low' || item.confidenceLevel === 'unknown' || item.conditionState === 'unknown') return TACTICAL.amber;
  if (item.confidenceLevel === 'medium') return '#65D4FF';
  return '#66BB6A';
}

function routeConfidenceTimelineMatchesRoute(
  timeline: RouteConfidenceTimeline | null,
  selectedRouteId: string | null | undefined,
  selectedRouteGeometryVersion: string | null | undefined,
): boolean {
  if (!timeline) return false;
  const expectedRouteId = selectedRouteId ?? 'navigate-route';
  return (
    timeline.routeId === expectedRouteId &&
    timeline.geometryVersion === selectedRouteGeometryVersion
  );
}

function routeConfidenceTimelineSourceName(
  source: RouteConfidenceTimelineItem['primaryDriver']['source'] | null | undefined,
): string {
  const label = routeConfidenceTimelineString(source?.label) ?? routeConfidenceTimelineString(source?.sourceType);
  return label ? label.replace(/_/g, ' ') : 'Unknown source';
}

function routeConfidenceTimelineTimestampLabel(value: string | null | undefined): string {
  if (!value) return 'unavailable';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
}

function routeConfidenceTimelineDriverSummary(item: RouteConfidenceTimelineItem): string {
  const drivers = item.contributingDrivers?.length ? item.contributingDrivers : item.drivers;
  const labels = Array.from(new Set(
    drivers
      .map((driver) => driver.category.replace(/_/g, ' '))
      .filter(Boolean),
  ));
  return labels.length ? labels.join(', ') : 'No contributing drivers';
}

function routeConfidenceTimelineHasLimitedSource(item: RouteConfidenceTimelineItem): boolean {
  const sources = item.sources?.length ? item.sources : item.sourceFreshness;
  return sources.some((source) =>
    source.freshness === 'stale' ||
    source.freshness === 'expired' ||
    source.freshness === 'missing' ||
    source.freshness === 'unavailable',
  );
}

function RouteConfidenceTimelinePanel({
  timeline,
  selectedItemId,
  onSelectItem,
}: {
  timeline: RouteConfidenceTimeline | null;
  selectedItemId: string | null;
  onSelectItem: (item: RouteConfidenceTimelineItem) => void;
}) {
  const selectedItem = timeline?.items.find((item) => item.id === selectedItemId) ?? timeline?.items[0] ?? null;
  const timelineUnavailable = !timeline || timeline.completeness === 'unavailable';
  const timelineLimited = timeline?.completeness === 'partial' || timeline?.completeness === 'source_limited';
  const notableOnly = timeline?.coverageMode === 'notable_spans_only';
  return (
    <View style={styles.routeConfidenceTimelinePanel}>
      <View style={styles.routeConfidenceTimelineHeader}>
        <View style={styles.routeConfidenceTimelineTitleBlock}>
          <Text style={styles.intelSectionTitle}>Route Confidence Timeline</Text>
          <Text style={styles.routeConfidenceTimelineSubtitle}>What certainty changes along this route?</Text>
        </View>
        <View style={styles.routeConfidenceTimelineBadge}>
          <Text style={styles.routeConfidenceTimelineBadgeText}>FEATURE-FLAGGED</Text>
        </View>
      </View>
      <Text style={styles.routeConfidenceTimelineSafetyCopy}>
        Unknown/low confidence means uncertainty, not confirmed danger.
      </Text>
      <Text style={styles.routeConfidenceTimelineSafetyCopy}>
        Timeline diagnostics do not affect route readiness or route choice.
      </Text>
      {timelineLimited ? (
        <Text style={styles.routeConfidenceTimelineSafetyCopy}>Timeline limited by available source data.</Text>
      ) : null}
      {notableOnly ? (
        <Text style={styles.routeConfidenceTimelineSafetyCopy}>Showing notable confidence changes only.</Text>
      ) : null}
      {timeline && timeline.items.length > 0 ? (
        <>
          <View style={styles.routeConfidenceTimelineTrack}>
            {timeline.items.map((item) => {
              const color = routeConfidenceTimelineTone(item);
              const selected = item.id === selectedItem?.id;
              return (
                <TouchableOpacity
                  key={item.id}
                  style={[
                    styles.routeConfidenceTimelineSpan,
                    {
                      flexGrow: Math.max(1, item.endMeasure - item.startMeasure),
                      borderColor: selected ? color : `${color}55`,
                      backgroundColor: `${color}${selected ? '44' : '24'}`,
                    },
                  ]}
                  activeOpacity={0.82}
                  onPress={() => onSelectItem(item)}
                  accessibilityRole="button"
                  accessibilityLabel={`Route confidence timeline segment ${item.label}`}
                />
              );
            })}
          </View>
          {selectedItem ? (
            <View style={styles.routeConfidenceTimelineDetail}>
              <Text style={styles.intelPrimaryLine}>{selectedItem.label}</Text>
              <Text style={styles.intelSecondaryLine}>{routeConfidenceTimelineItemCopy(selectedItem)}</Text>
              <Text style={styles.intelCalloutText}>
                {formatNavMeters(selectedItem.startMeasure)} to {formatNavMeters(selectedItem.endMeasure)} - {selectedItem.primaryDriver.category.replace(/_/g, ' ')}
              </Text>
              <Text style={styles.intelCalloutText}>
                Source: {routeConfidenceTimelineSourceName(selectedItem.primaryDriver.source)}
              </Text>
              <Text style={styles.intelCalloutText}>
                Freshness: {selectedItem.primaryDriver.source.freshness.replace(/_/g, ' ')}
              </Text>
              <Text style={styles.intelCalloutText}>
                Observed: {routeConfidenceTimelineTimestampLabel(selectedItem.primaryDriver.source.observedAt)}
              </Text>
              <Text style={styles.intelCalloutText}>
                Generated: {routeConfidenceTimelineTimestampLabel(selectedItem.primaryDriver.source.generatedAt)}
              </Text>
              <Text style={styles.intelCalloutText}>
                Expires: {routeConfidenceTimelineTimestampLabel(selectedItem.primaryDriver.source.expiresAt)}
              </Text>
              <Text style={styles.intelCalloutText}>
                Contributing drivers: {routeConfidenceTimelineDriverSummary(selectedItem)}
              </Text>
              {routeConfidenceTimelineHasLimitedSource(selectedItem) ? (
                <Text style={styles.intelCalloutText}>Stale/unavailable source metadata present.</Text>
              ) : null}
              {selectedItem.drivers.slice(0, 3).map((driver) => (
                <Text key={`${selectedItem.id}:${driver.id}`} style={styles.intelCalloutText}>
                  {driver.label}: {driver.confidenceLevel} confidence / {driver.conditionState.replace(/_/g, ' ')}
                </Text>
              ))}
            </View>
          ) : null}
        </>
      ) : (
        <Text style={styles.intelEmptyText}>
          {timelineUnavailable ? 'Route confidence timeline unavailable.' : 'No notable confidence changes from available sources.'}
        </Text>
      )}
    </View>
  );
}

function formatNavDuration(seconds: number | null | undefined): string {
  if (seconds == null || !Number.isFinite(seconds)) return '--';
  const rounded = Math.max(Math.round(seconds / 60), 1);
  if (rounded < 60) return `${rounded} min`;
  const hours = Math.floor(rounded / 60);
  const mins = rounded % 60;
  return mins > 0 ? `${hours}h ${mins}m` : `${hours}h`;
}

function formatNavEta(etaIso: string | null | undefined): string {
  if (!etaIso) return '--';
  const date = new Date(etaIso);
  if (Number.isNaN(date.getTime())) return '--';
  return date.toLocaleTimeString([], {
    hour: 'numeric',
    minute: '2-digit',
  });
}

function estimateActiveGuidanceExtensionDurationS(
  extensionDistanceM: number,
  baseDistanceM: number | null | undefined,
  baseDurationS: number | null | undefined,
): number | null {
  if (!Number.isFinite(extensionDistanceM) || extensionDistanceM <= 0) return null;
  const routeMetersPerSecond =
    baseDistanceM != null &&
    baseDurationS != null &&
    Number.isFinite(baseDistanceM) &&
    Number.isFinite(baseDurationS) &&
    baseDistanceM > 0 &&
    baseDurationS > 0
      ? baseDistanceM / baseDurationS
      : null;
  const fallbackTrailMetersPerSecond = 6.7;
  const metersPerSecond = Math.max(2, routeMetersPerSecond ?? fallbackTrailMetersPerSecond);
  return extensionDistanceM / metersPerSecond;
}

function formatNavTimestamp(value: string | null | undefined): string {
  if (!value) return 'Updated just now';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return 'Updated just now';
  return `Updated ${date.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })}`;
}

function coordinatesEqual(
  a: { lat: number; lng: number } | null | undefined,
  b: { lat: number; lng: number } | null | undefined,
): boolean {
  if (!a || !b) return false;
  return Math.abs(a.lat - b.lat) < 0.00001 && Math.abs(a.lng - b.lng) < 0.00001;
}

function tileBoundsIntersect(a: TileBounds | null | undefined, b: TileBounds | null | undefined): boolean {
  if (!a || !b) return false;
  return !(
    a.maxLat < b.minLat ||
    a.minLat > b.maxLat ||
    a.maxLng < b.minLng ||
    a.minLng > b.maxLng
  );
}

function tileBoundsContain(outer: TileBounds | null | undefined, inner: TileBounds | null | undefined): boolean {
  if (!outer || !inner) return false;
  return (
    outer.minLat <= inner.minLat &&
    outer.maxLat >= inner.maxLat &&
    outer.minLng <= inner.minLng &&
    outer.maxLng >= inner.maxLng
  );
}

function isRoadNavCoordinate(value: unknown): value is RoadNavCoordinate {
  const coord = value as Partial<RoadNavCoordinate> | null | undefined;
  const lat = Number(coord?.lat);
  const lng = Number(coord?.lng);
  return (
    Number.isFinite(lat) &&
    Number.isFinite(lng) &&
    lat >= -90 &&
    lat <= 90 &&
    lng >= -180 &&
    lng <= 180
  );
}

function getOfflineRouteDestination(route: OfflineCachedRoute): {
  destination: RoadNavDestination;
  usedMetadata: boolean;
} | null {
  const metadata = route.finalDestination;
  const metadataCoordinate = metadata
    ? { lat: Number(metadata.latitude), lng: Number(metadata.longitude) }
    : null;
  if (metadataCoordinate && isRoadNavCoordinate(metadataCoordinate)) {
    return {
      destination: {
        id: `offline-sync-destination:${route.id}`,
        title: metadata?.label || route.name || 'Offline route destination',
        subtitle: metadata?.subtitle ?? route.name ?? 'Saved offline route',
        coordinate: metadataCoordinate,
        sourceType: 'offline_sync_open',
        raw: { routeId: route.id, stableRouteKey: route.stableRouteKey },
      },
      usedMetadata: true,
    };
  }

  const lastPoint = route.routeGeometry?.[route.routeGeometry.length - 1];
  const fallbackCoordinate = lastPoint
    ? { lat: Number(lastPoint.latitude), lng: Number(lastPoint.longitude) }
    : null;
  if (!fallbackCoordinate || !isRoadNavCoordinate(fallbackCoordinate)) {
    return null;
  }

  return {
    destination: {
      id: `offline-sync-destination:${route.id}`,
      title: route.name || 'Offline route destination',
      subtitle: 'Recovered from saved route geometry',
      coordinate: fallbackCoordinate,
      sourceType: 'offline_sync_open',
      raw: { routeId: route.id, stableRouteKey: route.stableRouteKey, destinationMetadataMissing: true },
    },
    usedMetadata: false,
  };
}

function buildOfflineCachedRoadPreviewRoute(
  route: OfflineCachedRoute,
  origin: RoadNavCoordinate,
  destination: RoadNavDestination,
): RoadNavRoute | null {
  const geometry = (route.routeGeometry ?? [])
    .map((point) => ({ lat: Number(point.latitude), lng: Number(point.longitude) }))
    .filter(isRoadNavCoordinate);
  if (geometry.length < 1) return null;

  return buildRoadRouteFromCachedGeometry({
    id: `offline-sync-preview:${route.id}:${Date.now().toString(36)}`,
    origin,
    destination,
    geometry,
    distanceM:
      typeof route.routeDistanceMiles === 'number' && Number.isFinite(route.routeDistanceMiles)
        ? route.routeDistanceMiles * 1609.344
        : null,
    durationS: null,
    createdAt: new Date().toISOString(),
  });
}

function createRoadPreviewRunFromRoute(
  route: RoadNavRoute,
  fallbackBuildSnapshot?: Partial<BuildSnapshot> | null,
): ECSRun {
  const now = new Date().toISOString();
  const points = route.geometry.map((point, index) => ({
    idx: index,
    lat: point.lat,
    lng: point.lng,
    ele_m: null,
    time: null,
    type: 'route' as const,
  }));
  const first = points[0] ?? null;
  const last = points[points.length - 1] ?? null;
  const distanceM = Number.isFinite(route.distanceM) ? Math.max(0, route.distanceM) : 0;
  const buildSnapshot = {
    ...createDefaultBuildSnapshot(),
    ...(fallbackBuildSnapshot ?? {}),
    captured_at: now,
  };

  return {
    id: `road-preview-${route.id}`,
    user_id: null,
    title: route.destination.title || 'Road preview route',
    source: 'route',
    created_at: route.createdAt || now,
    updated_at: now,
    vehicle_id: buildSnapshot.vehicle_id,
    build_snapshot: buildSnapshot,
    stats: {
      distance_m: Math.round(distanceM),
      distance_miles: distanceM / 1609.344,
      distance_km: distanceM / 1000,
      point_count: points.length,
      start_lat: first?.lat ?? null,
      start_lng: first?.lng ?? null,
      end_lat: last?.lat ?? route.destination.coordinate.lat ?? null,
      end_lng: last?.lng ?? route.destination.coordinate.lng ?? null,
      elevation_gain_ft: null,
      elevation_loss_ft: null,
      min_ele_ft: null,
      max_ele_ft: null,
    },
    points,
    waypoints: [
      {
        lat: route.destination.coordinate.lat,
        lon: route.destination.coordinate.lng,
        ele: null,
        name: route.destination.title,
        time: null,
        waypointType: null,
      },
    ],
    is_active: false,
  };
}

function buildRouteIntentForRoadPreview(input: {
  route: RoadNavRoute;
  analysis: RouteAnalysis;
  mapStyle: string;
  readinessSnapshot?: unknown | null;
}): OfflineRouteIntentMetadata {
  const primaryRoadName =
    input.route.steps.find((step) => typeof step.roadName === 'string' && step.roadName.trim().length > 0)
      ?.roadName ?? input.route.destination.title;

  return {
    syncType: 'route',
    origin: {
      mode: 'gps',
      latitude: input.route.origin.lat,
      longitude: input.route.origin.lng,
      label: 'Current GPS location',
    },
    destination: {
      latitude: input.route.destination.coordinate.lat,
      longitude: input.route.destination.coordinate.lng,
      label: input.route.destination.title || 'Route destination',
      subtitle: input.route.destination.subtitle,
      source: 'route_geometry',
    },
    routeGeometryPointCount: input.route.geometry.length,
    encodedPolyline: null,
    routeSummary: {
      distanceMeters: input.route.distanceM,
      distanceMiles: input.route.distanceM / 1609.344,
      durationSeconds: input.route.durationS,
      primaryName: primaryRoadName,
    },
    mapContext: {
      styleKey: input.mapStyle,
      // Campsite visibility layers are marker/data overlays, not tile-cache layers.
      layerContext: ['route-corridor', 'road-preview'],
      zoomMin: input.analysis.zoomMin,
      zoomMax: input.analysis.zoomMax,
      corridorMiles: input.analysis.bufferMiles,
    },
    routeAnalysisSnapshot: input.analysis,
    readinessSnapshot: input.readinessSnapshot ?? null,
    preparedAt: new Date().toISOString(),
  };
}

function runRoutePoints(run: ECSRun): RoadNavCoordinate[] {
  return (Array.isArray(run.points) ? run.points : [])
    .map((point) => ({
      lat: Number(point.lat),
      lng: Number(point.lng),
    }))
    .filter((point) => Number.isFinite(point.lat) && Number.isFinite(point.lng));
}

function buildRouteIntentForSavedRouteRun(input: {
  run: ECSRun;
  routePoints: RoadNavCoordinate[];
  analysis: RouteAnalysis;
  mapStyle: string;
  readinessSnapshot?: unknown | null;
  source: 'saved_route_packet' | 'active_route_package';
}): OfflineRouteIntentMetadata {
  const first = input.routePoints[0] ?? null;
  const last = input.routePoints[input.routePoints.length - 1] ?? null;
  const distanceMeters =
    Number.isFinite(input.run.stats?.distance_m)
      ? input.run.stats.distance_m
      : Number.isFinite(input.run.stats?.distance_miles)
        ? input.run.stats.distance_miles * 1609.344
        : null;

  return {
    syncType: 'route',
    origin: {
      mode: 'saved_route_start',
      latitude: first?.lat ?? null,
      longitude: first?.lng ?? null,
      label: 'Saved route start',
    },
    destination: {
      latitude: last?.lat ?? input.run.stats?.end_lat ?? first?.lat ?? 0,
      longitude: last?.lng ?? input.run.stats?.end_lng ?? first?.lng ?? 0,
      label: input.run.title || 'Saved route destination',
      subtitle: `${String(input.run.source || 'saved route').toUpperCase()} route geometry`,
      source: 'route_geometry',
    },
    routeGeometryPointCount: input.routePoints.length,
    encodedPolyline: null,
    routeSummary: {
      distanceMeters,
      distanceMiles: Number.isFinite(input.run.stats?.distance_miles) ? input.run.stats.distance_miles : null,
      durationSeconds: null,
      primaryName: input.run.title || 'Saved route',
    },
    mapContext: {
      styleKey: input.mapStyle,
      layerContext: ['route-corridor', input.source],
      zoomMin: input.analysis.zoomMin,
      zoomMax: input.analysis.zoomMax,
      corridorMiles: input.analysis.bufferMiles,
    },
    routeAnalysisSnapshot: input.analysis,
    readinessSnapshot: input.readinessSnapshot ?? null,
    preparedAt: new Date().toISOString(),
  };
}

function sameConnectivitySnapshot(
  a: ConnectivityDetailedState,
  b: ConnectivityDetailedState,
): boolean {
  return (
    a.status === b.status &&
    a.level === b.level &&
    a.networkType === b.networkType &&
    a.isOnline === b.isOnline &&
    a.isInternetReachable === b.isInternetReachable &&
    a.latencyMs === b.latencyMs &&
    a.lastOnlineAt === b.lastOnlineAt &&
    a.lastOfflineAt === b.lastOfflineAt &&
    a.reconnectCount === b.reconnectCount &&
    a.initialized === b.initialized
  );
}

function sameTileCacheSnapshot(
  a: { regions: { id: string; status: string; downloadedTiles: number; tileCount: number }[]; stats: TileCacheStats },
  b: { regions: { id: string; status: string; downloadedTiles: number; tileCount: number }[]; stats: TileCacheStats },
): boolean {
  if (
    a.stats.totalRegions !== b.stats.totalRegions ||
    a.stats.totalTiles !== b.stats.totalTiles ||
    a.stats.downloadedTiles !== b.stats.downloadedTiles ||
    a.stats.totalSizeMB !== b.stats.totalSizeMB ||
    a.stats.lastDownloadAt !== b.stats.lastDownloadAt ||
    a.stats.storageQuotaMB !== b.stats.storageQuotaMB ||
    a.stats.storageUsedMB !== b.stats.storageUsedMB ||
    a.stats.deviceFreeMB !== b.stats.deviceFreeMB ||
    a.stats.deviceTotalMB !== b.stats.deviceTotalMB
  ) {
    return false;
  }

  if (a.regions.length !== b.regions.length) return false;
  for (let index = 0; index < a.regions.length; index += 1) {
    const left = a.regions[index];
    const right = b.regions[index];
    if (
      left.id !== right.id ||
      left.status !== right.status ||
      left.downloadedTiles !== right.downloadedTiles ||
      left.tileCount !== right.tileCount
    ) {
      return false;
    }
  }

  return true;
}

function sameRouteIntelligence(
  a: RouteIntelligence | null,
  b: RouteIntelligence | null,
): boolean {
  if (a === b) return true;
  if (!a || !b) return !a && !b;
  return (
    a.id === b.id &&
    a.sourceId === b.sourceId &&
    a.totalDistanceMiles === b.totalDistanceMiles &&
    a.segmentCount === b.segmentCount &&
    a.analyzedAt === b.analyzedAt
  );
}

