function sameRemotenessProximityEstimate(
  a: { distanceMi: number | null; confidence: string; source: string },
  b: { distanceMi: number | null; confidence: string; source: string },
): boolean {
  return a.distanceMi === b.distanceMi && a.confidence === b.confidence && a.source === b.source;
}

function sameRemotenessIndex(
  a: RemotenessIndexOutput | null,
  b: RemotenessIndexOutput | null,
): boolean {
  if (a === b) return true;
  if (!a || !b) return !a && !b;
  return (
    a.score === b.score &&
    a.rawScore === b.rawScore &&
    a.level === b.level &&
    a.levelColor === b.levelColor &&
    a.reason === b.reason &&
    a.description === b.description &&
    a.connectivity.signal === b.connectivity.signal &&
    a.connectivity.qualityScore === b.connectivity.qualityScore &&
    a.forecast.available === b.forecast.available &&
    a.forecast.peakScore === b.forecast.peakScore &&
    a.forecast.isIncreasing === b.forecast.isIncreasing &&
    a.advisories.length === b.advisories.length &&
    a.advisories[0]?.id === b.advisories[0]?.id &&
    a.advisories[0]?.message === b.advisories[0]?.message &&
    sameRemotenessProximityEstimate(a.proximity.nearestPavedRoad, b.proximity.nearestPavedRoad) &&
    sameRemotenessProximityEstimate(a.proximity.nearestTown, b.proximity.nearestTown) &&
    sameRemotenessProximityEstimate(a.proximity.nearestFuelStation, b.proximity.nearestFuelStation)
  );
}

function buildNavigationPayloadSignature(payload: NavigationHandoffPayload | null): string {
  if (!payload) return 'null';
  return JSON.stringify({
    id: payload.id,
    createdAt: payload.createdAt,
    tripMode: payload.tripMode ?? null,
    title: payload.title,
    subtitle: payload.subtitle ?? null,
    coordinate: payload.coordinate
      ? {
          lat: Number(payload.coordinate.lat).toFixed(5),
          lng: Number(payload.coordinate.lng).toFixed(5),
        }
      : null,
    roadDestinationCoordinate: payload.roadDestinationCoordinate
      ? {
          lat: Number(payload.roadDestinationCoordinate.lat).toFixed(5),
          lng: Number(payload.roadDestinationCoordinate.lng).toFixed(5),
        }
      : null,
    trailLengthMiles: payload.trailLengthMiles ?? null,
    trailGeometryCount: safeArray(payload.trailGeometry).length,
    trailGeometrySegmentCount: safeArray(payload.trailGeometrySegments).length,
    waypointCount: safeArray(payload.trailWaypoints).length,
    decisionPointCount: safeArray(payload.trailDecisionPoints).length,
    campMarkerCount: safeArray(payload.campMarkers).length,
    exploreAction:
      payload.routeMetadata && typeof payload.routeMetadata === 'object'
        ? (payload.routeMetadata as Record<string, unknown>).exploreAction ?? null
        : null,
    previewSource:
      payload.routeMetadata && typeof payload.routeMetadata === 'object'
        ? (payload.routeMetadata as Record<string, unknown>).previewSource ?? null
        : null,
    activeGuidanceUnavailableReason:
      payload.routeMetadata && typeof payload.routeMetadata === 'object'
        ? (payload.routeMetadata as Record<string, unknown>).activeGuidanceUnavailableReason ?? null
        : null,
    runId:
      payload.routeMetadata && typeof payload.routeMetadata === 'object'
        ? (payload.routeMetadata as Record<string, unknown>).runId ?? null
        : null,
  });
}

function sameNavigationPayload(
  a: NavigationHandoffPayload | null,
  b: NavigationHandoffPayload | null,
): boolean {
  if (a === b) return true;
  if (!a || !b) return !a && !b;
  return buildNavigationPayloadSignature(a) === buildNavigationPayloadSignature(b);
}

function isRestorableNavigationHandoffPayload(
  payload: NavigationHandoffPayload | null,
): payload is NavigationHandoffPayload {
  if (!payload?.id || !payload.title) return false;
  if (!isRecentIsoTimestamp(payload.createdAt, NAVIGATION_HANDOFF_RESTORE_MAX_AGE_MS)) {
    return false;
  }

  return (
    !!payload.coordinate ||
    !!payload.trailheadCoordinate ||
    !!payload.roadDestinationCoordinate ||
    safeArray(payload.trailGeometry).length > 1 ||
    safeArray(payload.trailGeometrySegments).some((segment) => safeArray(segment).length > 1)
  );
}

type RouteGeometryPlanningEndpoint = {
  latitude: number;
  longitude: number;
  segmentId: string;
  distanceMiles: number;
};

function coordinateEndpointScore(
  coordinate: RoadNavCoordinate | null | undefined,
  endpoint: RouteGeometryPlanningEndpoint,
): number {
  if (!coordinate || !Number.isFinite(coordinate.lat) || !Number.isFinite(coordinate.lng)) {
    return Number.POSITIVE_INFINITY;
  }
  return (coordinate.lat - endpoint.latitude) ** 2 + (coordinate.lng - endpoint.longitude) ** 2;
}

function applyRouteGeometryPlanningEndpoint(
  payload: NavigationHandoffPayload,
  endpoint: RouteGeometryPlanningEndpoint | null,
): NavigationHandoffPayload {
  if (!endpoint) return payload;
  const startCoordinate: RoadNavCoordinate = {
    lat: endpoint.latitude,
    lng: endpoint.longitude,
  };
  const trailGeometry = Array.isArray(payload.trailGeometry) ? payload.trailGeometry : [];
  const firstScore = coordinateEndpointScore(trailGeometry[0], endpoint);
  const lastScore = coordinateEndpointScore(trailGeometry[trailGeometry.length - 1], endpoint);
  const orientedTrailGeometry =
    trailGeometry.length > 1 && lastScore < firstScore
      ? [...trailGeometry].reverse()
      : trailGeometry;
  const rawRecord =
    payload.raw && typeof payload.raw === 'object' && !Array.isArray(payload.raw)
      ? (payload.raw as Record<string, unknown>)
      : {};

  return {
    ...payload,
    coordinate: orientedTrailGeometry[orientedTrailGeometry.length - 1] ?? payload.coordinate,
    trailheadCoordinate: startCoordinate,
    roadDestinationCoordinate: startCoordinate,
    trailGeometry: orientedTrailGeometry,
    routeMetadata: {
      ...(payload.routeMetadata ?? {}),
      routeGeometryPlanningSource: ROUTE_GEOMETRY_VIEWPORT_PLANNING_SOURCE,
      routeGeometryNearestEndpoint: endpoint,
      routeGeometryNearestEndpointBehavior:
        'Road navigation is staged from current GPS to the nearest selected ECS route geometry endpoint before trail guidance.',
    },
    raw: {
      ...rawRecord,
      routeGeometryPlanningSource: ROUTE_GEOMETRY_VIEWPORT_PLANNING_SOURCE,
      routeGeometryNearestEndpoint: endpoint,
    },
  };
}

function buildMapCameraCommandSignature(command: MapSurfaceCameraCommand | null): string {
  if (!command) return 'null';
  return JSON.stringify({
    mode: command.mode,
    center: command.center
      ? {
          latitude: Number(command.center.latitude).toFixed(5),
          longitude: Number(command.center.longitude).toFixed(5),
        }
      : null,
    zoom: command.zoom ?? null,
    durationMs: command.durationMs ?? null,
    animate: command.animate ?? null,
    reason: command.reason ?? null,
    fitBounds: command.fitBounds
      ? {
          north: Number(command.fitBounds.north).toFixed(5),
          south: Number(command.fitBounds.south).toFixed(5),
          east: Number(command.fitBounds.east).toFixed(5),
          west: Number(command.fitBounds.west).toFixed(5),
          padding: command.fitBounds.padding ?? null,
          maxZoom: command.fitBounds.maxZoom ?? null,
        }
      : null,
  });
}

function sameRunCollection(a: ECSRun[], b: ECSRun[]): boolean {
  if (a === b) return true;
  if (a.length !== b.length) return false;
  for (let index = 0; index < a.length; index += 1) {
    const left = a[index];
    const right = b[index];
    if (
      left.id !== right.id ||
      left.updated_at !== right.updated_at ||
      left.title !== right.title ||
      safeArray(left.points).length !== safeArray(right.points).length
    ) {
      return false;
    }
  }
  return true;
}

function samePinCollection(a: ECSPin[], b: ECSPin[]): boolean {
  if (a === b) return true;
  if (a.length !== b.length) return false;
  for (let index = 0; index < a.length; index += 1) {
    const left = a[index];
    const right = b[index];
    if (
      left.id !== right.id ||
      left.lat !== right.lat ||
      left.lng !== right.lng ||
      left.resolved !== right.resolved ||
      left.type !== right.type ||
      left.title !== right.title
    ) {
      return false;
    }
  }
  return true;
}

function sameTrailSegments(a: TrailSegmentData[], b: TrailSegmentData[]): boolean {
  if (a === b) return true;
  if (a.length !== b.length) return false;
  for (let index = 0; index < a.length; index += 1) {
    const left = a[index];
    const right = b[index];
    const leftCoordinateCount = Array.isArray(left.coordinates) ? left.coordinates.length : 0;
    const rightCoordinateCount = Array.isArray(right.coordinates) ? right.coordinates.length : 0;
    if (
      left.id !== right.id ||
      leftCoordinateCount !== rightCoordinateCount ||
      left.color !== right.color
    ) {
      return false;
    }
  }
  return true;
}

function sameRouteBuilderSegments(
  a: RouteBuilderSegmentData[],
  b: RouteBuilderSegmentData[],
): boolean {
  const normalizeCoord = (coord: any) => {
    const lng = Array.isArray(coord) ? coord[0] : coord?.longitude;
    const lat = Array.isArray(coord) ? coord[1] : coord?.latitude;
    return { lng: Number(lng ?? 0), lat: Number(lat ?? 0) };
  };
  const sameCoordinateList = (leftInput: any, rightInput: any) => {
    const left = Array.isArray(leftInput) ? leftInput : [];
    const right = Array.isArray(rightInput) ? rightInput : [];
    if (left.length !== right.length) return false;
    for (let pointIndex = 0; pointIndex < left.length; pointIndex += 1) {
      const leftCoord = normalizeCoord(left[pointIndex]);
      const rightCoord = normalizeCoord(right[pointIndex]);
      if (
        Math.abs(leftCoord.lng - rightCoord.lng) > 0.000001 ||
        Math.abs(leftCoord.lat - rightCoord.lat) > 0.000001
      ) {
        return false;
      }
    }
    return true;
  };
  if (a === b) return true;
  if (a.length !== b.length) return false;
  for (let index = 0; index < a.length; index += 1) {
    const left = a[index];
    const right = b[index];
    if (
      left.id !== right.id ||
      left.sourceSegmentId !== right.sourceSegmentId ||
      JSON.stringify(left.buildSource ?? null) !== JSON.stringify(right.buildSource ?? null) ||
      !sameCoordinateList(left.coordinates, right.coordinates) ||
      !sameCoordinateList(left.rawSegment, right.rawSegment) ||
      !sameCoordinateList(left.snappedSegment, right.snappedSegment)
    ) {
      return false;
    }
    if (
      left.snapConfidence !== right.snapConfidence ||
      left.snapSource !== right.snapSource ||
      left.snapStatus !== right.snapStatus ||
      left.snapProvider !== right.snapProvider ||
      left.snapProfile !== right.snapProfile ||
      left.snapMessage !== right.snapMessage
    ) {
      return false;
    }
  }
  return true;
}

function sourceMetadataForRouteBuilderSegment(segment: RouteBuilderSegmentData): RouteSegmentSourceMetadata {
  if (segment.buildSource) return segment.buildSource;
  return {
    kind: 'snapped_trace',
    sourceLabel: routeBuilderSegmentMetadataSourceLabel(segment),
    confidence: 'unknown',
  };
}

function routeGeometrySegmentToNavigateTraceableSegment(
  segment: RouteGeometryOverlaySegment,
): NavigateRouteTraceableSegment {
  return {
    id: segment.id,
    name: segment.name,
    sourceLabel: segment.sourceLabel,
    confidence: segment.confidence,
    dataState: segment.dataState,
    coordinates: segment.coordinates.map((point) => ({
      latitude: point.latitude,
      longitude: point.longitude,
    })),
    warnings: segment.warnings,
  };
}

function segmentPayloadToLongPressFeature(
  payload: any,
): NavigateLongPressRouteableFeature | null {
  if (!payload || typeof payload !== 'object') return null;
  const warnings = typeof payload.routeGeometryWarningsJson === 'string'
    ? (() => {
        try {
          const parsed = JSON.parse(payload.routeGeometryWarningsJson);
          return Array.isArray(parsed) ? parsed.filter((item) => typeof item === 'string') : [];
        } catch {
          return [];
        }
      })()
    : [];
  const coordinates = payloadLineToNavigateRouteCoordinates(payload.coordinates);
  return {
    id: payload.id ?? null,
    kind: payload.kind ?? null,
    name: payload.name ?? payload.categoryLabel ?? null,
    sourceLabel: payload.routeGeometrySourceKind ?? payload.categoryLabel ?? payload.name ?? null,
    confidence: payload.routeGeometryConfidence ?? payload.confidence ?? null,
    dataState: payload.routeGeometryDataState ?? payload.dataState ?? null,
    coordinates: coordinates.length >= 2 ? coordinates : null,
    connectedSegments: Array.isArray(payload.connectedSegments)
      ? payload.connectedSegments
          .slice(0, 96)
          .map((segment: any) => segmentPayloadToLongPressFeature({ ...segment, connectedSegments: null }))
          .filter((segment: NavigateLongPressRouteableFeature | null): segment is NavigateLongPressRouteableFeature => !!segment)
      : null,
    warnings,
  };
}

function payloadLineToNavigateRouteCoordinates(value: unknown): NavigateRouteCoordinate[] {
  if (!Array.isArray(value)) return [];
  const coordinates: NavigateRouteCoordinate[] = [];
  value.forEach((point) => {
    const coordinate = toNavigateRouteCoordinate(point as any);
    if (!coordinate) return;
    const previous = coordinates[coordinates.length - 1];
    if (
      previous &&
      Math.abs(previous.latitude - coordinate.latitude) <= 0.0000005 &&
      Math.abs(previous.longitude - coordinate.longitude) <= 0.0000005
    ) {
      return;
    }
    coordinates.push(coordinate);
  });
  return coordinates;
}

function routeableFeatureToNavigateTraceableSegment(
  feature: NavigateLongPressRouteableFeature | null | undefined,
): NavigateRouteTraceableSegment | null {
  const coordinates = payloadLineToNavigateRouteCoordinates(feature?.coordinates ?? null);
  if (coordinates.length < 2) return null;
  const provider =
    String(feature?.kind ?? '').toLowerCase() === 'rendered_routeable_feature'
      ? 'rendered_features'
      : 'ecs_route_geometry';
  const id =
    String(feature?.id ?? '').trim() ||
    `${provider}:${coordinates[0].latitude.toFixed(5)},${coordinates[0].longitude.toFixed(5)}:${coordinates[coordinates.length - 1].latitude.toFixed(5)},${coordinates[coordinates.length - 1].longitude.toFixed(5)}`;
  return {
    id,
    name: feature?.name ?? null,
    sourceLabel:
      feature?.sourceLabel ??
      feature?.name ??
      (provider === 'rendered_features' ? 'Visible routeable geometry' : 'ECS route geometry'),
    confidence: feature?.confidence ?? (provider === 'rendered_features' ? 'medium' : 'unknown'),
    dataState: feature?.dataState ?? null,
    provider,
    coordinates,
    warnings: feature?.warnings ?? null,
  };
}

function routeableFeatureToNavigateTraceableSegments(
  feature: NavigateLongPressRouteableFeature | null | undefined,
): NavigateRouteTraceableSegment[] {
  const candidates = [feature, ...(feature?.connectedSegments ?? [])];
  const seen = new Set<string>();
  const segments: NavigateRouteTraceableSegment[] = [];
  candidates.forEach((candidate) => {
    const segment = routeableFeatureToNavigateTraceableSegment(candidate);
    if (!segment) return;
    const first = segment.coordinates[0];
    const last = segment.coordinates[segment.coordinates.length - 1];
    const signature = `${segment.id}:${first.latitude.toFixed(6)},${first.longitude.toFixed(6)}:${last.latitude.toFixed(6)},${last.longitude.toFixed(6)}:${segment.coordinates.length}`;
    if (seen.has(signature)) return;
    seen.add(signature);
    segments.push(segment);
  });
  return segments;
}

function toNavigateRouteCoordinate(
  coordinate: { latitude?: number; longitude?: number; lat?: number; lng?: number } | [number, number] | null | undefined,
): NavigateRouteCoordinate | null {
  const latitude = Array.isArray(coordinate)
    ? Number(coordinate[1])
    : Number(coordinate?.latitude ?? coordinate?.lat);
  const longitude = Array.isArray(coordinate)
    ? Number(coordinate[0])
    : Number(coordinate?.longitude ?? coordinate?.lng);
  if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) return null;
  if (Math.abs(latitude) > 90 || Math.abs(longitude) > 180) return null;
  return { latitude, longitude };
}

function routeBuilderFinalSnapSignature(segment: RouteBuilderSegmentData): string {
  const line = normalizeRouteBuilderLine(
    Array.isArray(segment.rawSegment) && segment.rawSegment.length > 1
      ? segment.rawSegment
      : segment.coordinates,
  );
  return line.map((coordinate) => `${coordinate[0].toFixed(6)},${coordinate[1].toFixed(6)}`).join(';');
}

function shouldPreserveRouteBuilderFinalSnapState(
  existing: RouteBuilderSegmentData | undefined,
  incoming: RouteBuilderSegmentData,
): existing is RouteBuilderSegmentData {
  if (!existing) return false;
  if (routeBuilderFinalSnapSignature(existing) !== routeBuilderFinalSnapSignature(incoming)) return false;
  return (
    existing.snapStatus === 'network_pending' ||
    existing.snapStatus === 'blocked' ||
    existing.snapProvider === 'mapbox_map_matching' ||
    (existing.snapProvider === 'rendered_features' && incoming.snapProvider == null)
  );
}

function mergeRouteBuilderFinalSnapState(
  incomingSegments: RouteBuilderSegmentData[],
  existingSegments: RouteBuilderSegmentData[],
): RouteBuilderSegmentData[] {
  return incomingSegments.map((incoming) => {
    const existing = existingSegments.find((segment) => segment.id === incoming.id);
    return shouldPreserveRouteBuilderFinalSnapState(existing, incoming) ? existing : incoming;
  });
}

function toTrailSegmentData(
  segments: { segment_id: string; coordinates: [number, number][] }[],
): TrailSegmentData[] {
  return segments.map((segment, index) => ({
    id: segment.segment_id || `trail-segment-${index}`,
    coordinates: safeArray(segment.coordinates),
    color: '#D4A017',
  }));
}

function routePointsFromTrailSegment(segment: TrailSegmentData): RoadNavCoordinate[] {
  const coordinates = Array.isArray(segment.coordinates)
    ? (segment.coordinates as ([number, number] | { latitude: number; longitude: number })[])
    : [];
  return coordinates
    .map((coordinate) => ({
      lat: Number(Array.isArray(coordinate) ? coordinate[1] : coordinate.latitude),
      lng: Number(Array.isArray(coordinate) ? coordinate[0] : coordinate.longitude),
    }))
    .filter((point) =>
      Number.isFinite(point.lat) &&
      Number.isFinite(point.lng) &&
      Math.abs(point.lat) <= 90 &&
      Math.abs(point.lng) <= 180,
    );
}

type NavigateOperationalMode =
  | 'live'
  | 'syncing'
  | 'degraded'
  | 'offline_cached_route'
  | 'offline_partial_map'
  | 'offline_unavailable';

type NavigateOperationalState = {
  mode: NavigateOperationalMode;
  tone: 'live' | 'degraded' | 'offline' | 'unavailable';
  label: string;
  previewStatusLabel: string | null;
  activeStatusLabel: string | null;
  searchLabel: string;
  searchDetail: string | null;
  activeDetail: string;
  previewDetail: string;
  liveSearchAvailable: boolean;
  liveRoutingAvailable: boolean;
  hasRouteSupport: boolean;
  hasMapCoverage: boolean;
};

function joinOperationalStatus(
  base: string | null | undefined,
  operational: string | null | undefined,
): string {
  const normalizedBase = base?.trim();
  const normalizedOperational = operational?.trim();
  if (!normalizedBase) return normalizedOperational ?? '';
  if (!normalizedOperational) return normalizedBase;
  return `${normalizedBase} | ${normalizedOperational}`;
}


function replaceVisibleAIWithECS(input: string): string {
  return input
    .replace(/\bAI\b/g, 'ECS')
    .replace(/\bA\.I\.\b/g, 'ECS')
    .replace(/\bai\b/g, 'ecs');
}

function sanitizeVisibleLanguage<T>(value: T, seen: WeakMap<object, unknown> = new WeakMap()): T {
  if (typeof value === 'string') {
    return replaceVisibleAIWithECS(value) as T;
  }
  if (Array.isArray(value)) {
    if (seen.has(value)) return seen.get(value) as T;
    const next: unknown[] = [];
    seen.set(value, next);
    value.forEach((item) => {
      next.push(sanitizeVisibleLanguage(item, seen));
    });
    return next as T;
  }
  if (value && typeof value === 'object') {
    if (seen.has(value)) return seen.get(value) as T;
    const next: Record<string, unknown> = {};
    seen.set(value, next);
    Object.entries(value as Record<string, unknown>).forEach(([key, child]) => {
      next[key] = sanitizeVisibleLanguage(child, seen);
    });
    return next as T;
  }
  return value;
}

