const handleCommitRouteBuilderSave = useCallback(async () => {
  const name = routeBuilderSaveName.trim();
  const note = routeBuilderSaveNote.trim();
  const description = routeBuilderActiveExtensionMode
    ? note
      ? `kind: 'active_guidance_extension'. NOTE: ${note}`
      : "kind: 'active_guidance_extension'. Original active guidance plus operator-added continuation legs."
    : note
      ? `kind: 'pin_to_pin_anchor_trace'. NOTE: ${note}`
      : "kind: 'pin_to_pin_anchor_trace'. Built from dropped route anchors.";
  const result = await saveVerifiedRouteBuilderDraft({
    name: name || null,
    description,
    sourceApp: routeBuilderActiveExtensionMode ? 'ecs_active_guidance_extension' : 'ecs_anchor_route_builder',
    externalSourceType: routeBuilderActiveExtensionMode ? 'active_guidance_extension' : 'pin_to_pin_anchor_trace',
  });
  if (!result) return;
  setRouteBuilderSaveVisible(false);
  setRouteBuilderSaveName('');
  setRouteBuilderSaveNote('');
}, [routeBuilderActiveExtensionMode, routeBuilderSaveName, routeBuilderSaveNote, saveVerifiedRouteBuilderDraft]);

const routeToRouteBuilder = useCallback(async () => {
  hapticCommand();
  const origin = safeUserLocation
    ? { latitude: safeUserLocation.lat, longitude: safeUserLocation.lng }
    : null;
  if (!origin) {
    showToast('START NEEDS GPS');
    return;
  }
  const startPlan = buildRouteFromNearestAnchor(routeBuilderDraft, origin);
  const entryAnchor = resolveNearestNavigateRouteAnchor(routeBuilderDraft, origin);
  const startCoordinates = startPlan.coordinates.map((point) => [point.longitude, point.latitude] as [number, number]);
  const startSegments: RouteBuilderSegmentData[] | null = startCoordinates.length > 1
    ? [{
        id: 'route-builder-nearest-anchor-start',
        coordinates: startCoordinates,
        rawSegment: startCoordinates,
        snappedSegment: startCoordinates,
        snapConfidence: 'medium',
        snapSource: 'nearest_anchor_trace',
        snapStatus: 'snapped' as const,
        snapProvider: 'ecs_route_geometry' as const,
        snapProfile: null,
        snapMessage: `Starting from nearest dropped anchor ${entryAnchor?.label ?? ''}.`,
        sourceSegmentId: entryAnchor?.id ?? null,
        buildSource: {
          kind: 'ecs_route_geometry',
          sourceLabel: 'Nearest dropped route anchor',
          confidence: 'planning_geometry',
        },
      }]
    : null;
  await saveVerifiedRouteBuilderDraft({
    stage: true,
    autoStart: true,
    name: 'Route To Drawn Route',
    sourceApp: 'ecs_anchor_route_builder',
    externalSourceType: 'pin_to_pin_anchor_trace',
    description: "kind: 'pin_to_pin_anchor_trace_start'. Starts from current GPS to the nearest dropped route anchor.",
    segmentsOverride: startSegments,
    routeGeometryStartEndpoint: entryAnchor
      ? {
          latitude: entryAnchor.coordinate.latitude,
          longitude: entryAnchor.coordinate.longitude,
          segmentId: entryAnchor.id,
          distanceMiles: 0,
        }
      : null,
  });
}, [
  routeBuilderDraft,
  safeUserLocation,
  saveVerifiedRouteBuilderDraft,
  showToast,
]);

const handlePlanRouteBuilderDraft = useCallback(async () => {
  hapticCommand();
  if (!routeBuilderCanPlanGeometry) {
    showToast('SELECT SAVEABLE ECS GEOMETRY FIRST');
    return;
  }

  const result = await saveVerifiedRouteBuilderDraft({
    sourceApp: 'ecs_route_geometry_overlay',
    externalSourceType: 'route_geometry_overlay',
    description: `kind: 'route_geometry_overlay'. ${ROUTE_GEOMETRY_OVERLAY_PLANNING_WARNING}`,
  });
  if (!result) return;

  const { savedRoute } = result;
  const routeGeometryCoordinates = savedRoute.segments
    .map((segment) =>
      segment.points
        .map((point) => [point.lon, point.lat])
        .filter(([longitude, latitude]) => Number.isFinite(longitude) && Number.isFinite(latitude)),
    )
    .filter((line) => line.length > 1);
  const trailGeometry = savedRoute.segments.flatMap((segment) =>
    segment.points
      .map((point) => ({
        latitude: point.lat,
        longitude: point.lon,
      }))
      .filter((point) => Number.isFinite(point.latitude) && Number.isFinite(point.longitude)),
  );
  const nearestRouteGeometryEndpoint = routeGeometryNearestPlanningEndpoint;
  const startCoordinate = nearestRouteGeometryEndpoint
    ? {
        latitude: nearestRouteGeometryEndpoint.latitude,
        longitude: nearestRouteGeometryEndpoint.longitude,
      }
    : trailGeometry[0] ?? null;
  const endCoordinate = trailGeometry[trailGeometry.length - 1] ?? null;
  const tripBuilderRoute: TripBuilderRouteInput = {
    id: savedRoute.id,
    name: savedRoute.name,
    title: savedRoute.name,
    source: 'ecs_route_geometry_overlay',
    distanceMiles: savedRoute.total_distance_miles,
    total_distance_miles: savedRoute.total_distance_miles,
    coordinate: startCoordinate,
    destinationCoordinate: endCoordinate,
    endCoordinate,
    routeGeometry:
      routeGeometryCoordinates.length > 0
        ? {
            type: 'MultiLineString',
            coordinates: routeGeometryCoordinates,
          }
        : null,
    routeGeometryStatus: 'trail_available',
    trailGeometry,
    segments: savedRoute.segments,
    routeMetadata: {
      sourceApp: 'ecs_route_geometry_overlay',
      sourceLabel: 'ECS Route Geometry Overlay',
      sourceState: savedRoute.sync_status,
      routeGeometryPlanningSource: ROUTE_GEOMETRY_VIEWPORT_PLANNING_SOURCE,
      routeGeometryNearestEndpoint: nearestRouteGeometryEndpoint,
      routeGeometryWarning: ROUTE_GEOMETRY_OVERLAY_PLANNING_WARNING,
      routeGeometryConfidence:
        'planning/reference geometry - not legal access, closure, or safety approval',
    },
  };

  saveTripBuilderRouteHandoff(tripBuilderRoute);
  router.push({
      pathname: '/explore-trip-builder',
    params: { routeId: savedRoute.id },
  } as any);
  showToast(`TRIP BUILDER READY: ${savedRoute.name}`);
}, [
  routeBuilderCanPlanGeometry,
  routeGeometryNearestPlanningEndpoint,
  router,
  saveVerifiedRouteBuilderDraft,
  showToast,
]);

