const handleRoadOverlayReroute = useCallback(() => {
  if (trailNavigationUiMode === 'active' || pendingHybridTrailTransition) {
    if (trailRejoinPoint) {
      fitMapToCoordinatePreview(
        trailRejoinPoint,
        88,
        'trail_rejoin',
      );
    } else if (userLocation) {
      fitMapToCoordinatePreview(userLocation, 72, 'trail_center');
    } else {
      showToast?.('Trail route centered.');
    }
    return;
  }
  void rerouteRoadNavigation('manual');
}, [
  fitMapToCoordinatePreview,
  pendingHybridTrailTransition,
  rerouteRoadNavigation,
  showToast,
  trailNavigationUiMode,
  trailRejoinPoint,
  userLocation,
]);

const handleMapLifecycleMetrics = useCallback((payload: {
  label?: string;
  before?: MapLifecycleSnapshot | null;
  after?: MapLifecycleSnapshot | null;
} | null) => {
  const after = payload?.after ?? null;
  if (!after) return;
  const before = previousMapLifecycleSnapshotRef.current ?? payload?.before ?? after;
  recordMapLifecycleSample(exploreNavigateSeparationRunRef.current, {
    label: payload?.label ?? 'navigate_map',
    before,
    after,
  });
  previousMapLifecycleSnapshotRef.current = after;
}, []);

